insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0c0ff613-9be9-5eea-b41b-fd6d6853b2b5', 'Random mutations give some bacteria resistance [1]; when antibiotics are used, susceptible bacteria die and resistant ones survive (natural selection) [1]; survivors reproduce and pass on resistance genes (also via plasmids), so resistance becomes more frequent [1].', 'Random mutations give some bacteria resistance [1]; when antibiotics are used, susceptible bacteria die and resistant ones survive (natural selection) [1]; survivors reproduce and pass on resistance genes (also via plasmids), so resistance becomes more frequent [1].', '[{"text": "Marking point 1", "any": ["mutation", "random"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["survive", "selection"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["reproduce", "pass on", "frequency", "plasmid"], "all": [], "marks": 1}]'::jsonb, 'Random mutations give some bacteria resistance [1]; when antibiotics are used, susceptible bacteria die and resistant ones survive (natural selection) [1]; survivors reproduce and pass on resistance genes (also via plasmids), so resistance becomes more frequent [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
