insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('94267598-cd1d-5583-bed7-ab5df1a014bc', 'Thermoreceptors detect the rise and the hypothalamus coordinates the response [1]; skin arterioles dilate so more blood flows near the surface and loses heat [1]; sweat glands secrete sweat which cools the skin as it evaporates [1].', 'Thermoreceptors detect the rise and the hypothalamus coordinates the response [1]; skin arterioles dilate so more blood flows near the surface and loses heat [1]; sweat glands secrete sweat which cools the skin as it evaporates [1].', '[{"text": "Marking point 1", "any": ["hypothalamus", "thermoreceptor"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["vasodilation", "dilate", "blood to skin"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["sweat", "evaporat"], "all": [], "marks": 1}]'::jsonb, 'Thermoreceptors detect the rise and the hypothalamus coordinates the response [1]; skin arterioles dilate so more blood flows near the surface and loses heat [1]; sweat glands secrete sweat which cools the skin as it evaporates [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
